const lockCanvasPlacementOutputs = `-- name: LockCanvasPlacementOutputs :many
SELECT o.id FROM outputs o WHERE o.company_id=$1 AND EXISTS(
 SELECT 1 FROM canvas_version_sources v JOIN project_artifacts a ON a.id=v.artifact_id
 WHERE v.access_output_id=o.id AND a.project_id=$2 AND a.archived_at IS NULL
) ORDER BY o.id FOR SHARE
`

type LockCanvasPlacementOutputsParams struct {
	CompanyID uuid.UUID `json:"company_id"`
	ProjectID uuid.UUID `json:"project_id"`
}

// Match the source lifecycle fence used by single placement. The following
// INSERT rechecks access after these locks, in a fresh READ COMMITTED statement.
func (q *Queries) LockCanvasPlacementOutputs(ctx context.Context, arg LockCanvasPlacementOutputsParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, lockCanvasPlacementOutputs, arg.CompanyID, arg.ProjectID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

