const placeCanvasOutputArtifact = `-- name: PlaceCanvasOutputArtifact :many
WITH occupied AS (
 SELECT x,y,width,height FROM canvas_items
 WHERE project_id=$2::uuid AND deleted_at IS NULL
), bounds AS (
 SELECT count(*) AS total,GREATEST(40,COALESCE(max(y+height)+40,40))::double precision AS bottom FROM occupied
), tail AS (
 SELECT x+width+40 AS x,y FROM occupied ORDER BY y DESC,x DESC LIMIT 1
), candidate AS (
 SELECT COALESCE(t.x,40)::double precision AS x,COALESCE(t.y,40)::double precision AS y
 FROM (SELECT 1) seed LEFT JOIN tail t ON true
), position AS (
 SELECT c.x, c.y,c.x>=40 AND c.x+320<=1800 AND NOT EXISTS(
  SELECT 1 FROM occupied o WHERE c.x<o.x+o.width+20 AND c.x+340>o.x
   AND c.y<o.y+o.height+20 AND c.y+300>o.y
 ) AS fits FROM candidate c
)
INSERT INTO canvas_items(company_id,project_id,canvas_id,item_type,artifact_id,pinned_version_id,x,y,width,height,created_by_user_id)
SELECT $1::uuid,$2::uuid,$3::uuid,
 'artifact',$4::uuid,$5::uuid,
 CASE WHEN p.fits THEN p.x ELSE 40 END,CASE WHEN p.fits THEN p.y ELSE b.bottom END,
 320,280,$6::uuid
FROM position p CROSS JOIN bounds b WHERE b.total<2000 RETURNING id
`

type PlaceCanvasOutputArtifactParams struct {
	CompanyID   uuid.UUID `json:"company_id"`
	ProjectID   uuid.UUID `json:"project_id"`
	CanvasID    uuid.UUID `json:"canvas_id"`
	ArtifactID  uuid.UUID `json:"artifact_id"`
	VersionID   uuid.UUID `json:"version_id"`
	ActorUserID uuid.UUID `json:"actor_user_id"`
}

// The caller holds the canvas row lock. Append to the last row when there is
// space; otherwise start below existing work. Never move an authored card.
func (q *Queries) PlaceCanvasOutputArtifact(ctx context.Context, arg PlaceCanvasOutputArtifactParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, placeCanvasOutputArtifact,
		arg.CompanyID,
		arg.ProjectID,
		arg.CanvasID,
		arg.ArtifactID,
		arg.VersionID,
		arg.ActorUserID,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const placeUnplacedCanvasArtifacts = `-- name: PlaceUnplacedCanvasArtifacts :many
WITH candidates AS (
 SELECT a.id,v.id AS version_id,row_number() OVER(ORDER BY a.created_at,a.id)-1 AS ordinal
 FROM project_artifacts a
 JOIN LATERAL (
  SELECT pv.id FROM canvas_version_sources pv WHERE pv.artifact_id=a.id
  AND (pv.access_output_id IS NULL OR EXISTS(SELECT 1 FROM output_access acl WHERE acl.output_id=pv.access_output_id AND acl.user_id=$4::uuid))
AND ((pv.source_type='wiki' AND pv.wiki_revision_id IS NOT NULL) OR (pv.source_type='file' AND pv.asset_version_id IS NOT NULL)
  OR (pv.source_type='output' AND EXISTS(SELECT 1 FROM output_access oa WHERE oa.output_id=pv.output_id AND oa.user_id=$4::uuid)))
  ORDER BY pv.number DESC LIMIT 1
 ) v ON true
 WHERE a.company_id=$1::uuid AND a.project_id=$2::uuid AND a.archived_at IS NULL
 AND NOT EXISTS(
  SELECT 1 FROM canvas_items i JOIN canvas_version_sources placed ON placed.id=CASE WHEN i.version_policy='accepted' THEN a.accepted_version_id ELSE i.pinned_version_id END
  WHERE i.artifact_id=a.id AND i.deleted_at IS NULL
  AND (placed.access_output_id IS NULL OR EXISTS(SELECT 1 FROM output_access acl WHERE acl.output_id=placed.access_output_id AND acl.user_id=$4::uuid))
AND ((placed.source_type='wiki' AND placed.wiki_revision_id IS NOT NULL) OR (placed.source_type='file' AND placed.asset_version_id IS NOT NULL)
  OR (placed.source_type='output' AND EXISTS(SELECT 1 FROM output_access oa WHERE oa.output_id=placed.output_id AND oa.user_id=$4::uuid)))
 )
), bounds AS (
 SELECT COALESCE(max(y+height)+80,40)::double precision AS bottom FROM canvas_items WHERE project_id=$2::uuid AND deleted_at IS NULL
)
INSERT INTO canvas_items(company_id,project_id,canvas_id,item_type,artifact_id,pinned_version_id,x,y,width,height,created_by_user_id)
SELECT $1::uuid,$2::uuid,$3::uuid,'artifact',c.id,c.version_id,
 40+(c.ordinal%5)*360,b.bottom+(c.ordinal/5)*320,320,280,$4::uuid
FROM candidates c CROSS JOIN bounds b RETURNING id
`

type PlaceUnplacedCanvasArtifactsParams struct {
	CompanyID   uuid.UUID `json:"company_id"`
	ProjectID   uuid.UUID `json:"project_id"`
	CanvasID    uuid.UUID `json:"canvas_id"`
	ActorUserID uuid.UUID `json:"actor_user_id"`
}

func (q *Queries) PlaceUnplacedCanvasArtifacts(ctx context.Context, arg PlaceUnplacedCanvasArtifactsParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, placeUnplacedCanvasArtifacts,
		arg.CompanyID,
		arg.ProjectID,
		arg.CanvasID,
		arg.ActorUserID,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

